function factorial(n) {
  if (n <= 1) return 1;
  return n * factorial(n - 1);
}

console.log(factorial(5));

const button = document.querySelector('#start');
button.addEventListener('click', () => {
  button.textContent = 'Go!';
  button.disabled = true;
});

document.addEventListener('keydown', (event) => {
  if (event.key === 'Escape') {
    console.log('Paused');
  }
});

async function loadTexts() {
  const response = await fetch('/api/texts?mode=words&lang=en');
  if (!response.ok) {
    throw new Error(`HTTP ${response.status}`);
  }
  return response.json();
}

const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function countdown() {
  for (const n of [3, 2, 1]) {
    console.log(n);
    await wait(1000);
  }
  console.log('Go!');
}

function wpm(chars, ms) {
  if (ms === 0) return 0;
  return chars / 5 / (ms / 60000);
}

console.log(wpm(250, 60000).toFixed(1));

const multiplier = (combo) => {
  if (combo >= 100) return 5;
  if (combo >= 50) return 3;
  if (combo >= 20) return 2;
  return 1;
};

class Car {
  constructor(name, number) {
    this.name = name;
    this.number = number;
  }

  toString() {
    return `#${this.number} ${this.name}`;
  }
}

console.log(String(new Car('McQueen', 95)));

